<?php if ($rows): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Permohonan</th><th>Hari tera</th><th>Jumlah aset</th><th>Dipinjam</th><th>Oleh</th><th>Dikembalikan</th><th>Status</th></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr><td data-label="Permohonan"><a class="table-link" href="<?= site_url('petugas/permohonan/'.$row->request_id.'?tab=ctt') ?>"><?= e($row->request_no) ?></a></td><td data-label="Hari tera"><?= e(tanggal_id($row->loan_date)) ?></td><td data-label="Jumlah aset"><?= (int)$row->asset_units ?></td><td data-label="Dipinjam"><?= e(tanggal_id($row->borrowed_at,TRUE)) ?></td><td data-label="Oleh"><?= e($row->borrower_name ?: '—') ?></td><td data-label="Dikembalikan"><?= $row->returned_at?e(tanggal_id($row->returned_at,TRUE)):'—' ?></td><td data-label="Status"><?php if ($row->returned_at && substr($row->returned_at,0,10)>$row->loan_date): ?><span class="badge warning">Kembali terlambat</span><?php elseif ($row->returned_at): ?><span class="badge success">Kembali</span><?php elseif ($row->loan_date<date('Y-m-d')): ?><span class="badge danger">Belum kembali</span><?php else: ?><span class="badge warning">Dipinjam</span><?php endif; ?><?php if ($row->cancelled_at): ?><small>Pilihan dihapus: <?= e($row->cancel_reason) ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php else: ?><div class="table-empty">Belum ada peminjaman harian CTT ini.</div><?php endif; ?>
